require(['jquery'],function($){'use strict';$(function(){var intervalMs=3000;var timer=null;function startAutoplay(){stopAutoplay();timer=setInterval(function(){var $f=$('.fotorama');if($f.length&&$f.data('fotorama')){try{var api=$f.data('fotorama');api.show((api.activeIndex+1)%api.size);return;}catch(e){}}},intervalMs);}
function stopAutoplay(){if(timer){clearInterval(timer);timer=null;}}
if($('.product.media, .gallery, .fotorama, .owl-carousel').length){startAutoplay();$('.product.media, .gallery, .fotorama').on('mouseenter',stopAutoplay).on('mouseleave',startAutoplay);}});});